mapper.select:
select sum(money) as money,user_id
from ums_account_records where 1 = 1

    AND create_time >= #{paramCondition.startDate}


    AND user_id = #{paramCondition.userId}

select umar.*,um.realname as memberName,um.phone as memberPhone from ums_account_records umar left join sys_user um on um.id=umar.user_id where 1 = 1
and umar.user_id = #{paramCondition.userId}
and umar.account_type = #{paramCondition.accountType}
and ( um.realname like CONCAT('%',#{paramCondition.keyword},'%') or um.phone like CONCAT('%',#{paramCondition.keyword},'%') or umar.content like CONCAT('%',#{paramCondition.keyword},'%') )
and umar.create_time >= #{paramCondition.startDate} and umar.create_time < #{paramCondition.endDate}
order by umar.create_time desc
